{
  "incident": {
    "component": "db-7",
    "category": "Infrastructure - Disk Space",
    "status": "firing",
    "summary": "Critical disk space alert on database node db-7."
  },
  "assessment": {
    "urgency": "critical",
    "rationale": "Database disk exhaustion can lead to data corruption, service downtime, and inability to write new transactions."
  },
  "facts": [
    "Alert type: disk alert",
    "Target: db-7",
    "Severity: critical"
  ],
  "missing_context": [
    {
      "item": "Disk usage percentage/amount",
      "why": "To determine if the disk is nearly full or completely exhausted",
      "how_to_check": "ssh db-7 'df -h'"
    },
    {
      "item": "Partition identity",
      "why": "To know if it is the OS partition, data partition, or log partition",
      "how_to_check": "ssh db-7 'df -h'"
    },
    {
      "item": "Growth rate",
      "why": "To distinguish between a sudden spike and a slow leak",
      "how_to_check": "Prometheus/Grafana disk usage trends"
    }
  ],
  "immediate_actions": [
    {
      "action": "Identify large files/directories",
      "purpose": "Locate the source of disk consumption",
      "conditions": "Immediately upon access",
      "expected_effect": "Identification of logs, temp files, or data growth",
      "risks": "None",
      "requires_approval": false,
      "verify": "Output of du command",
      "rule_ids": [
        "DISK_001"
      ]
    },
    {
      "action": "Clear old log files or temporary files",
      "purpose": "Regain immediate disk headroom",
      "conditions": "If logs or temp files are identified as the cause",
      "expected_effect": "Increased free disk space",
      "risks": "Loss of historical log data if not archived",
      "requires_approval": false,
      "verify": "df -h",
      "rule_ids": [
        "DISK_002"
      ]
    }
  ],
  "investigation_steps": [
    {
      "step": "Check database WAL/Redo logs",
      "hypothesis": "Database transaction logs are not being truncated or archived properly",
      "how_to_check": "ls -lh /var/lib/mysql/ (or equivalent path)"
    },
    {
      "step": "Check for large deleted files still held by processes",
      "hypothesis": "A file was deleted but the process still holds the file descriptor, preventing space reclamation",
      "how_to_check": "lsof +L1"
    }
  ],
  "root_cause_hypotheses": [
    "Unbounded log growth",
    "Database data volume exceeding provisioned capacity",
    "Large temporary files created by long-running queries",
    "Failure of automated cleanup/rotation scripts"
  ],
  "dangerous_operations": [
    {
      "operation": "Deleting database data files (.ibd, .db, etc.)",
      "why_dangerous": "Will cause immediate database corruption and data loss",
      "rule_id": "DB_DATA_PROTECT"
    },
    {
      "operation": "Truncating active database logs",
      "why_dangerous": "Can break replication or prevent database startup",
      "rule_id": "DB_LOG_PROTECT"
    }
  ],
  "applied_expert_rules": [
    "DISK_001",
    "DISK_002"
  ],
  "incident_update": "🚨 *Incident Alert*: Critical disk space alert on `db-7`. Investigating current usage and identifying large files. Will update once headroom is restored. #ops-incidents"
}
